pub fn readLines(io: std.Io, path: []const u8) ![]const []const u8 {
    const value = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited);
    const lines = split(value, '\n');
    return lines[0 .. lines.len - 1];
}
pub fn real(value: []const u8) f64 {
    return std.fmt.parseFloat(f64, value) catch unreachable;
}
fn readData(io: std.Io, path: []const u8) ![]const Example {
    const lines = try readLines(io, path);
    var out: std.ArrayList(Example) = .empty;
    for (lines[1..]) |line| {
        const row = split(line, ',');
        append(Example, &out, .{ .id = row[0], .point = .{ real(row[1]), real(row[2]) }, .label = number(row[3]) });
    }
    return out.items;
}
pub fn load(io: std.Io) !Input {
    var params: Params = .{};
    for (try readLines(io, "input/params.txt")) |line| {
        const row = words(line);
        const key = row[0];
        if (eq(key, "C_GRID")) {
            const values = alloc(f64, row.len - 1);
            for (row[1..], values) |field, *value| value.* = real(field);
            params.c_grid = values;
        } else if (eq(key, "KERNEL")) {
            var kernel: Kernel = .{ .name = row[1], .kind = std.meta.stringToEnum(KernelKind, row[2]).? };
            if (kernel.kind == .poly) {
                kernel.degree = u(number(row[3]));
                kernel.gamma = real(row[4]);
                kernel.coef0 = real(row[5]);
            } else if (kernel.kind == .rbf) kernel.gamma = real(row[3]);
            append(Kernel, &params.kernels, kernel);
        } else if (eq(key, "TOLERANCE")) params.tolerance = real(row[1]) else if (eq(key, "EPS")) params.epsilon = real(row[1]) else if (eq(key,
             "MAX_PASSES")) params.max_passes = u(number(row[1])) else if (eq(key, "FOLDS")) params.folds = u(number(row[1])) else if (eq(key,
        }
    }
    return .{ .train = try readData(io, "input/train.csv"), .test_data = try readData(io, "input/test.csv"),
         .multi_train = multi_train.items, .multi_test = multi_test.items, .params = params };
}
pub fn value(kernel: c.Kernel, a: c.Point, b: c.Point) f64 {
    if (kernel.kind == .linear) return a[0] * b[0] + a[1] * b[1];
    if (kernel.kind == .poly) {
        const s = kernel.gamma * (a[0] * b[0] + a[1] * b[1]) + kernel.coef0;
        var out: f64 = 1;
        for (0..kernel.degree) |_| out *= s;
        return out;
    }
    const e1 = a[0] - b[0];
    const e2 = a[1] - b[1];
    return @exp(-kernel.gamma * (e1 * e1 + e2 * e2));
}
pub fn matrix(kernel: c.Kernel, data: []const c.Example) c.Matrix {
    const out = c.alloc([]f64, data.len);
    for (out, 0..) |*row, i| {
        row.* = c.alloc(f64, data.len);
        for (row.*, 0..) |*entry, j| entry.* = value(kernel, data[i].point, data[j].point);
    }
    return out;
}
pub fn sign(value: f64) i64 {
    return if (value > 0) 1 else -1;
}
pub const Fold = struct { train: []const usize, test_data: []const usize };
pub fn folds(count: usize, k: usize) []Fold {
    const out = c.alloc(Fold, k);
    for (out, 0..) |*fold, phi| {
        var training: std.ArrayList(usize) = .empty;
        var testing: std.ArrayList(usize) = .empty;
        for (0..count) |i| {
            if (i % k == phi) c.append(usize, &testing, i) else c.append(usize, &training, i);
        }
        fold.* = .{ .train = training.items, .test_data = testing.items };
    }
    return out;
}
    pub fn decision(self: Model, point: c.Point) f64 {
        var out: f64 = 0;
        for (self.alpha, self.data) |alpha, example| if (alpha > 0) {
            out += alpha * c.f(example.label) * kernels.value(self.kernel, example.point, point);
        };
        return out - self.b;
    }
pub fn train(data: []const c.Example, kernel: c.Kernel, matrix: c.Matrix, coefficient: f64, params: c.Params) Model {
    const alpha = c.alloc(f64, data.len);
    @memset(alpha, 0);
    var errors: [200]f64 = undefined;
    for (data, 0..) |example, i| errors[i] = -c.f(example.label);
    var trainer: Trainer = .{ .model = .{ .data = data, .kernel = kernel, .matrix = matrix,
         .c = coefficient, .alpha = alpha }, .params = params, .errors = errors[0..data.len] };
    return trainer.run();
}
fn selectedData(data: []const c.Example, indices: []const usize) []const c.Example {
    const out = c.alloc(c.Example, indices.len);
    for (indices, out) |index, *example| example.* = data[index];
    return out;
}
fn selectedMatrix(matrix: c.Matrix, indices: []const usize) c.Matrix {
    const out = c.alloc([]f64, indices.len);
    for (out, 0..) |*row, i| {
        row.* = c.alloc(f64, indices.len);
        for (row.*, 0..) |*value, j| value.* = matrix[indices[i]][indices[j]];
    }
    return out;
}
fn decisions(model: smo.Model, data: []const c.Example) []f64 {
    const out = c.alloc(f64, data.len);
    for (data, out) |example, *value| value.* = model.decision(example.point);
    return out;
}
const Support = struct { total: i64 = 0, bound: i64 = 0, free: i64 = 0, by_bound: [2]i64 = .{ 0,
     0 }, by_free: [2]i64 = .{ 0, 0 } };
fn support(model: smo.Model) Support {
    var out: Support = .{};
    for (model.alpha, model.data) |alpha, example| if (alpha > 0) {
        out.total += 1;
        const label: usize = if (example.label == 1) 0 else 1;
        if (alpha == model.c) {
            out.bound += 1;
            out.by_bound[label] += 1;
        } else {
            out.free += 1;
            out.by_free[label] += 1;
        }
    };
    return out;
}
const FoldResult = struct { train: usize, test_count: usize, correct: i64, sv: i64, passes: usize,
     steps: usize, converged: bool };
const CV = struct { kernel: usize, candidate: usize, correct: i64 = 0, sv: i64 = 0, passes: usize = 0,
     steps: usize = 0, values: []f64, folds: []FoldResult };
fn foldModel(input: c.Input, kernel: c.Kernel, matrix: c.Matrix, coefficient: f64, fold: e.Fold,
     values: []f64) FoldResult {
    var scratch = std.heap.ArenaAllocator.init(c.backing_allocator);
    defer scratch.deinit();
    const previous = c.allocator;
    c.allocator = scratch.allocator();
    defer c.allocator = previous;
    const model = smo.train(selectedData(input.train, fold.train), kernel, selectedMatrix(matrix,
         fold.train), coefficient, input.params);
    var correct: i64 = 0;
    for (fold.test_data) |index| {
        values[index] = model.decision(input.train[index].point);
        correct += @intFromBool(e.sign(values[index]) == input.train[index].label);
    }
    return .{ .train = fold.train.len, .test_count = fold.test_data.len, .correct = correct,
         .sv = support(model).total, .passes = model.passes.items.len, .steps = model.steps,
         .converged = model.converged };
}
fn crossValidate(input: c.Input, kernel: usize, candidate: usize, matrix: c.Matrix) CV {
    var out: CV = .{ .kernel = kernel, .candidate = candidate, .values = c.alloc(f64, input.train.len),
         .folds = c.alloc(FoldResult, input.params.folds) };
    for (e.folds(input.train.len, input.params.folds), out.folds) |fold, *record| {
        record.* = foldModel(input, input.params.kernels.items[kernel], matrix, input.params.c_grid[candidate],
             fold, out.values);
        out.correct += record.correct;
        out.sv += record.sv;
        out.passes += record.passes;
        out.steps += record.steps;
    }
    return out;
}
fn metrics(input: c.Input, model: smo.Model) Metrics {
    var out: Metrics = .{ .training = model.trainingDecisions(), .testing = decisions(model,
         input.test_data), .sv = support(model) };
    return out;
}
